"""Task-local inspection: find SQLite databases and their schema in the workspace."""
import os
import sqlite3

for entry in sorted(os.listdir(".")):
    if entry.startswith("."):
        continue
    full = os.path.join(".", entry)
    print(f"{entry}  (dir)" if os.path.isdir(full) else entry)

print("\n--- SQLite candidates ---")
for entry in sorted(os.listdir(".")):
    if os.path.isdir(entry):
        continue
    if entry.endswith((".db", ".sqlite", ".sqlite3", ".db3")):
        print(f"\n=== {entry} ===")
        try:
            with sqlite3.connect(entry) as conn:
                cur = conn.cursor()
                tables = cur.execute(
                    "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
                ).fetchall()
                print("tables:", [t[0] for t in tables])
                for (table,) in tables:
                    cols = cur.execute(f'PRAGMA table_info("{table}")').fetchall()
                    print(f"  {table}: " + ", ".join(f"{c[1]} {c[2]}" for c in cols))
        except sqlite3.Error as exc:
            print(f"  not a usable sqlite file: {exc}")

